import{_ as n,o as i,c as t,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Wohn- und Umweltsicherheit","description":"","frontmatter":{},"headers":[],"relativePath":"de/0039-住房与环境保障.md","filePath":"de/0039-住房与环境保障.md"}'),s={name:"de/0039-住房与环境保障.md"};function u(l,e,h,a,o,d){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="wohn-und-umweltsicherheit" tabindex="-1">Wohn- und Umweltsicherheit <a class="header-anchor" href="#wohn-und-umweltsicherheit" aria-label="Permalink to &quot;Wohn- und Umweltsicherheit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projekt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>39</td></tr><tr><td>Modul</td><td>Zivilisationstypologie und Sozialsystem</td></tr><tr><td>Kernschlüsselwörter</td><td>Wohnsicherheit, Umweltschutz, ökologische Symbiose, bewohnbarer Raum, nachhaltige Entwicklung</td></tr></tbody></table><h2 id="i-kernkonzept-der-wohn-und-umweltsicherheit" tabindex="-1">I. Kernkonzept der Wohn- und Umweltsicherheit <a class="header-anchor" href="#i-kernkonzept-der-wohn-und-umweltsicherheit" aria-label="Permalink to &quot;I. Kernkonzept der Wohn- und Umweltsicherheit&quot;">​</a></h2><p>&quot;Wer wohnt, hat sein eigenes Haus&quot; ist ein grundlegendes Lebenshaltungsproblem, dem jede Zivilisation gegenüberstehen muss. In der Ära des räuberischen Kultivierungssystems wurden Wohnraum und Land von wenigen Starken und Sekten monopolisiert, und die Wesen der unteren Schicht hatten oft keinen festen Wohnsitz und waren gezwungen, in schlechten Umgebungen zu kultivieren und zu leben. Noch schwerwiegender ist, dass die räuberische Kultivierung enorme Umweltschäden verursacht hat — spirituelle Adern wurden übermäßig abgebaut, Ökosysteme wurden schwer verschmutzt, planetare Ressourcen wurden räuberisch verbraucht, was dazu führte, dass viele einst bewohnbare Planeten zu Ödland wurden.</p><p>Nach der Gründung der Anker-Symbiose-Zivilisation wurden Wohnsicherheit und Umweltschutz als Kerninhalt des Sozialsystemaufbaus betrachtet. Das Kernkonzept der Wohn- und Umweltsicherheit lässt sich in sechzehn Zeichen zusammenfassen: &quot;Wer wohnt, hat Haus, ökologische Symbiose, nachhaltige Entwicklung, alle Rassen bewohnbar&quot;.</p><p>Die Kernziele der Wohn- und Umweltsicherheit umfassen:</p><ol><li><strong>Grundwohnsitzrecht sicherstellen</strong>: Sicherstellen, dass jedes symbiotische Wesen würdige, sichere und angemessene Wohnungen erhalten kann, und dass Wohnprobleme das Überleben und die Evolution nicht beeinträchtigen</li><li><strong>Ökologische Umwelt schützen</strong>: Ein vollständiges Umweltschutzsystem aufbauen, das ökologische Gleichgewicht aufrechterhalten und Umweltschäden durch Kultivierungsaktivitäten verhindern</li><li><strong>Bewohnbaren Raum bauen</strong>: Durch wissenschaftliche Planung und technische Mittel einen für Kultivierung und Leben geeigneten bewohnbaren Raum bauen</li><li><strong>Nachhaltige Entwicklung verwirklichen</strong>: Bei der Befriedigung der Bedürfnisse der gegenwärtigen Generation die Fähigkeit zukünftiger Generationen zur Befriedigung ihrer eigenen Bedürfnisse nicht beeinträchtigen und die nachhaltige Nutzung von Ressourcen und Umwelt verwirklichen</li><li><strong>Bewohnbarkeit aller Rassen fördern</strong>: Beim Wohn- und Umweltbau die physiologischen Merkmale und Lebensgewohnheiten verschiedener Rassen voll berücksichtigen und sicherstellen, dass alle Rassen bewohnbar sind</li></ol><h2 id="ii-system-der-wohnsicherheit" tabindex="-1">II. System der Wohnsicherheit <a class="header-anchor" href="#ii-system-der-wohnsicherheit" aria-label="Permalink to &quot;II. System der Wohnsicherheit&quot;">​</a></h2><p>Das System der Wohnsicherheit der symbiotischen Zivilisation folgt den Prinzipien &quot;Grundlegendes sichern, Verbesserung fördern, mehrere Kanäle, nachhaltig&quot; und hat ein mehrstufiges Wohnversorgungssystem aufgebaut:</p><h3 id="_2-1-drei-ebenen-der-wohnversorgung" tabindex="-1">2.1 Drei Ebenen der Wohnversorgung <a class="header-anchor" href="#_2-1-drei-ebenen-der-wohnversorgung" aria-label="Permalink to &quot;2.1 Drei Ebenen der Wohnversorgung&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ebene</th><th>Name</th><th>Versorgungsgruppe</th><th>Wohntyp</th><th>Miete/Verkaufspreis</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Sozialwohnung</td><td>Niedrigverdiener, Anfänger-Kultivierer</td><td>Basis-Kultivierungswohnung, Kollektivheim</td><td>Kostenlos oder sehr niedrige Miete</td></tr><tr><td>Zweite Ebene</td><td>Verbesserungswirtschaft</td><td>Mittelverdiener, mittlere Kultivierer</td><td>Standard-Kultivierungswirtschaft, Familienwohnung</td><td>Selbstkostenpreis oder niedrige Miete</td></tr><tr><td>Dritte Ebene</td><td>Gewerbliche Wohnung</td><td>Hochverdiener, fortgeschrittene Kultivierer</td><td>Hochwertige Kultivierungswirtschaft, unabhängige Höhle</td><td>Marktpreis</td></tr></tbody></table><h3 id="_2-2-system-der-sozialwohnungen" tabindex="-1">2.2 System der Sozialwohnungen <a class="header-anchor" href="#_2-2-system-der-sozialwohnungen" aria-label="Permalink to &quot;2.2 System der Sozialwohnungen&quot;">​</a></h3><p>Sozialwohnungen sind der Kern des Wohnsicherheitssystems und gewährleisten das Grundwohnsitzrecht jedes symbiotischen Wesens:</p><ul><li><strong>Basis-Kultivierungswohnung</strong>: Kleine Wohnungen für Anfänger-Kultivierer und Einzelpersonen, ausgestattet mit grundlegenden Kultivierungseinrichtungen, Miete sehr niedrig oder kostenlos</li><li><strong>Kollektivheim</strong>: Kollektivunterkünfte für Sektenjünger, Studenten, Kollektivarbeiter, mit öffentlichem Kultivierungsraum</li><li><strong>Familien-Sozialwohnung</strong>: Komplette Wohnungen für einkommensschwache Familien, moderate Fläche, vollständige Einrichtungen</li><li><strong>Spezielle Sozialwohnung</strong>: Angepasste Wohnungen für spezielle Gruppen wie behinderte Wesen, spezielle Rassen, ältere Kultivierer usw.</li></ul><p>Die Beantragung und Zuweisung von Sozialwohnungen folgt den Prinzipien &quot;offen, fair, gerecht&quot;, erfolgt über das Symbiosenetzwerk zur Beantragung und Prüfung, und die Zuweisungsergebnisse sind offen und transparent.</p><h3 id="_2-3-system-der-verbesserungswirtschaften" tabindex="-1">2.3 System der Verbesserungswirtschaften <a class="header-anchor" href="#_2-3-system-der-verbesserungswirtschaften" aria-label="Permalink to &quot;2.3 System der Verbesserungswirtschaften&quot;">​</a></h3><p>Verbesserungswirtschaften richten sich an mittelständische Gruppen mit一定的 wirtschaftlicher Leistungsfähigkeit und werden zu Selbstkostenpreisen oder niedrigen Mieten angeboten:</p><ul><li><strong>Standard-Kultivierungswirtschaft</strong>: Komplette Wohnungen mit unabhängigem Kultivierungsraum, geeignet für Einzelpersonen und Familien mit一定的 Kultivierungsgrundlage</li><li><strong>Familienwohnung</strong>: Mittelgroße Wohnungen geeignet für Familienleben, mit Kinderaktivitätsraum und Familien-Kultivierungsbereich</li><li><strong>Talentwohnung</strong>: Vorzugswohnungen für importierte Hochtalente und Fachtechniker</li></ul><p>Die Versorgungsmenge der Verbesserungswirtschaften wird dynamisch an die Nachfrage angepasst, um sicherzustellen, dass mittelständische Gruppen zu angemessenen Kosten angemessene Wohnungen erhalten können.</p><h3 id="_2-4-system-der-gewerblichen-wohnungen" tabindex="-1">2.4 System der gewerblichen Wohnungen <a class="header-anchor" href="#_2-4-system-der-gewerblichen-wohnungen" aria-label="Permalink to &quot;2.4 System der gewerblichen Wohnungen&quot;">​</a></h3><p>Gewerbliche Wohnungen richten sich an Hochverdiener und werden zu Marktpreisen angeboten:</p><ul><li><strong>Hochwertige Kultivierungswirtschaft</strong>: Luxuswohnungen ausgestattet mit fortgeschrittenen Kultivierungseinrichtungen</li><li><strong>Unabhängige Höhle</strong>: Kultivierungshöhlen mit unabhängigem Raum und Energieversorgung</li><li><strong>Maßgeschneiderte Wohnung</strong>: Spezielle Wohnungen, die nach individuellen Bedürfnissen maßgeschneidert sind</li></ul><p>Der Handel mit gewerblichen Wohnungen folgt den Marktregeln, aber die Regierung reguliert durch Grundsteuer, Landverwaltung usw. und verhindert übermäßige Preissteigerungen bei Wohnungen und Immobilienspekulation.</p><h3 id="_2-5-kultivierungsraum-einrichtungen" tabindex="-1">2.5 Kultivierungsraum-Einrichtungen <a class="header-anchor" href="#_2-5-kultivierungsraum-einrichtungen" aria-label="Permalink to &quot;2.5 Kultivierungsraum-Einrichtungen&quot;">​</a></h3><p>Die Wohnungen der symbiotischen Zivilisation sind nicht nur Wohnräume, sondern auch Kultivierungsräume. Jede Wohnung ist entsprechend den Kultivierungsbedürfnissen des Bewohners mit entsprechenden Kultivierungseinrichtungen ausgestattet:</p><ul><li><strong>Basis-Kultivierungsbereich</strong>: Jede Wohnung hat einen Basis-Kultivierungsbereich, ausgestattet mit grundlegender Energieanschluss-Schnittstelle</li><li><strong>Energieversorgung</strong>: Über das Ankernetzwerk stabile Energieversorgung für die Wohnung bereitstellen, um die Kultivierungsbedürfnisse zu decken</li><li><strong>Schallschutz</strong>: Der Kultivierungsbereich verfügt über Schalldämmungs- und Energieschutzeinrichtungen, um zu verhindern, dass die Kultivierung andere stört</li><li><strong>Öffentlicher Kultivierungsraum</strong>: Die Gemeinde verfügt über öffentlichen Kultivierungssaal, Kultivierungsgeräteraum und andere gemeinsame Räume</li></ul><h2 id="iii-system-des-umweltschutzes" tabindex="-1">III. System des Umweltschutzes <a class="header-anchor" href="#iii-system-des-umweltschutzes" aria-label="Permalink to &quot;III. System des Umweltschutzes&quot;">​</a></h2><p>Das System des Umweltschutzes der symbiotischen Zivilisation folgt den Prinzipien &quot;Prävention vorrangig, umfassende Behandlung, ökologische Wiederherstellung, nachhaltige Nutzung&quot; und hat einen umfassenden Umweltschutzrahmen aufgebaut:</p><h3 id="_3-1-umweltstandards-und-aufsicht" tabindex="-1">3.1 Umweltstandards und -aufsicht <a class="header-anchor" href="#_3-1-umweltstandards-und-aufsicht" aria-label="Permalink to &quot;3.1 Umweltstandards und -aufsicht&quot;">​</a></h3><p>Die symbiotische Zivilisation hat strenge Umweltstandards festgelegt und die Umweltauswirkungen von Kultivierungs- und Produktionsaktivitäten reguliert:</p><ul><li><strong>Energieemissionsstandard</strong>: Strenge Begrenzung der im Kultivierungs- und Produktionsprozess erzeugten Energieemissionen</li><li><strong>Ressourcenabbau-Standard</strong>: Regulierung des Abbaus von spirituellen Adern, Mineralien, biologischen Ressourcen usw., Verhinderung übermäßigen Abbaus</li><li><strong>Ökologische Schutzlinie</strong>: Festlegung der ökologischen Schutzlinie, innerhalb derer jede zerstörerische Aktivität verboten ist</li><li><strong>Umweltverträglichkeitsprüfung</strong>: Große Kultivierungsingenieurprojekte und Bauprojekte müssen eine Umweltverträglichkeitsprüfung durchführen</li></ul><p>Die Umweltschutzaufsicht liegt bei spezialisierten Umweltaufsichtsbehörden, die über das Symbiosenetzwerk die Umweltqualität in Echtzeit überwachen und illegale Aktivitäten streng bestrafen.</p><h3 id="_3-2-verschmutzungsbehandlungstechnologie" tabindex="-1">3.2 Verschmutzungsbehandlungstechnologie <a class="header-anchor" href="#_3-2-verschmutzungsbehandlungstechnologie" aria-label="Permalink to &quot;3.2 Verschmutzungsbehandlungstechnologie&quot;">​</a></h3><p>Die symbiotische Zivilisation hat fortschrittliche Verschmutzungsbehandlungstechnologie entwickelt:</p><ul><li><strong>Energieverschmutzungsbehandlung</strong>: Durch Technologien wie Energiefilterung, Energieumwandlung usw. die durch Kultivierungsaktivitäten erzeugte Energieverschmutzung behandeln</li><li><strong>Materialverschmutzungsbehandlung</strong>: Durch Technologien wie biologische Wiederherstellung, chemische Behandlung, physikalische Reinigung usw. die Materialverschmutzung behandeln</li><li><strong>Gesetzesverschmutzungsbehandlung</strong>: Durch Technologien wie Gesetzesablösung, Gesetzesneutralisierung usw. die durch Gesetzeserosion verursachte Umweltverschmutzung behandeln</li><li><strong>Ökologische Wiederherstellungstechnologie</strong>: Durch das Lebenszyklussystem und ökologische Ingenieurtechnologie beschädigte Ökosysteme wiederherstellen</li></ul><h3 id="_3-3-nachhaltige-nutzung-von-ressourcen" tabindex="-1">3.3 Nachhaltige Nutzung von Ressourcen <a class="header-anchor" href="#_3-3-nachhaltige-nutzung-von-ressourcen" aria-label="Permalink to &quot;3.3 Nachhaltige Nutzung von Ressourcen&quot;">​</a></h3><p>Die symbiotische Zivilisation betont die nachhaltige Nutzung von Ressourcen und widersetzt sich der räuberischen Entwicklung:</p><ul><li><strong>Ressourcenabbau-Kontingent</strong>: Implementierung eines Abbau-Kontingentsystems für nicht erneuerbare Ressourcen, um die langfristige Nutzung der Ressourcen sicherzustellen</li><li><strong>Ressourcenkreislaufnutzung</strong>: Weitreichende Entwicklung der Ressourcenkreislaufnutzungstechnologie, Verbesserung der Ressourcennutzungseffizienz</li><li><strong>Entwicklung erneuerbarer Energien</strong>: Aktive Entwicklung erneuerbarer Energien wie Solarenergie, Windenergie, Wasserkraft, Energiefeldenergie usw.</li><li><strong>Forschung und Entwicklung alternativer Ressourcen</strong>: Forschung und Entwicklung von Ersatzstoffen für knappe Ressourcen, Reduzierung der Abhängigkeit von knappen Ressourcen</li></ul><h3 id="_3-4-okologischer-schutz-und-wiederherstellung" tabindex="-1">3.4 Ökologischer Schutz und Wiederherstellung <a class="header-anchor" href="#_3-4-okologischer-schutz-und-wiederherstellung" aria-label="Permalink to &quot;3.4 Ökologischer Schutz und Wiederherstellung&quot;">​</a></h3><p>Die symbiotische Zivilisation legt großen Wert auf ökologischen Schutz und Wiederherstellung:</p><ul><li><strong>Naturschutzgebiete</strong>: Aufbau von Naturschutzgebieten auf verschiedenen Ebenen, Schutz seltener Arten und primitiver Ökosysteme</li><li><strong>Ökologische Wiederherstellungsprojekte</strong>: Wiederherstellung bereits zerstörter Ökosysteme, Wiederherstellung des ökologischen Gleichgewichts</li><li><strong>Artenschutzprogramme</strong>: Schutz und Züchtung bedrohter Arten, Verhinderung des Artensterbens</li><li><strong>Ökologischer Ausgleichsmechanismus</strong>: Entschädigung für Regionen und Gruppen, die durch ökologischen Schutz Verluste erlitten haben</li></ul><h2 id="iv-bau-des-bewohnbaren-raums" tabindex="-1">IV. Bau des bewohnbaren Raums <a class="header-anchor" href="#iv-bau-des-bewohnbaren-raums" aria-label="Permalink to &quot;IV. Bau des bewohnbaren Raums&quot;">​</a></h2><p>Auf der Grundlage von Wohn- und Umweltsicherheit fördert die symbiotische Zivilisation den Bau des bewohnbaren Raums nachdrücklich:</p><h3 id="_4-1-stadtplanung" tabindex="-1">4.1 Stadtplanung <a class="header-anchor" href="#_4-1-stadtplanung" aria-label="Permalink to &quot;4.1 Stadtplanung&quot;">​</a></h3><p>Die Stadtplanung der symbiotischen Zivilisation folgt den Prinzipien &quot;kompakt, grün, smart, humanistisch&quot;:</p><ul><li><strong>Kompaktes Layout</strong>: Die Stadt采用 kompaktes Layout, reduziert Landnutzung und Verkehrsenergieverbrauch</li><li><strong>Grüner Raum</strong>: Erhaltung ausreichender grüner Flächen wie Grünflächen, Parks, Feuchtgebiete usw. in der Stadt</li><li><strong>Smart Management</strong>: Durch das Ankernetzwerk und Smart-Technologie das Smart-Management der Stadt verwirklichen</li><li><strong>Humanistische Fürsorge</strong>: Die Stadtplanung berücksichtigt die Bedürfnisse verschiedener Rassen, Altersgruppen und Fähigkeitsgruppen voll</li></ul><h3 id="_4-2-bau-von-kultivierungsgemeinschaften" tabindex="-1">4.2 Bau von Kultivierungsgemeinschaften <a class="header-anchor" href="#_4-2-bau-von-kultivierungsgemeinschaften" aria-label="Permalink to &quot;4.2 Bau von Kultivierungsgemeinschaften&quot;">​</a></h3><p>Die symbiotische Zivilisation baut nachdrücklich Kultivierungsgemeinschaften, die Wohnen, Kultivierung und Dienstleistungen integrieren:</p><ul><li><strong>Gemeinschaftliches Kultivierungszentrum</strong>: Jede Gemeinde hat ein Kultivierungszentrum, das öffentlichen Kultivierungsraum und Kultivierungsanleitung bietet</li><li><strong>Gemeinschaftliches Dienstleistungszentrum</strong>: Bereitstellung umfassender Dienstleistungen wie medizinische Versorgung, Bildung, Handel, Unterhaltung usw.</li><li><strong>Gemeinschaftsgrünfläche</strong>: Erhaltung ausreichender Grünflächen und Freizeiträume innerhalb der Gemeinde</li><li><strong>Gemeinschaftskultur</strong>: Pflege der Gemeinschaftskultur, Stärkung des Zugehörigkeitsgefühls und Zusammenhalts der Bewohner</li></ul><h3 id="_4-3-interdimensionale-bewohnbare-raume" tabindex="-1">4.3 Interdimensionale bewohnbare Räume <a class="header-anchor" href="#_4-3-interdimensionale-bewohnbare-raume" aria-label="Permalink to &quot;4.3 Interdimensionale bewohnbare Räume&quot;">​</a></h3><p>Mit dem Fortschritt der interdimensionalen Erforschung beginnt die symbiotische Zivilisation, bewohnbare Räume in anderen Ebenen zu bauen:</p><ul><li><strong>Ebenen-bewohnbare Umgestaltung</strong>: Durchführung bewohnbarer Umgestaltung für Ebenen mit geeigneten Bedingungen, Bau neuer Wohn- und Kultivierungsräume</li><li><strong>Ökologische Migration</strong>: Geplante Migration der Bevölkerung von ressourcenknappen Ebenen zu neu entwickelten bewohnbaren Ebenen</li><li><strong>Interdimensionale Wohnung</strong>: Bereitstellung interdimensionaler Wohnsicherheit für Kultivierer, die häufig zwischen Ebenen reisen</li></ul><h2 id="v-unterschiede-im-wohn-und-umweltmodell-der-funf-zivilisationstypologien" tabindex="-1">V. Unterschiede im Wohn- und Umweltmodell der fünf Zivilisationstypologien <a class="header-anchor" href="#v-unterschiede-im-wohn-und-umweltmodell-der-funf-zivilisationstypologien" aria-label="Permalink to &quot;V. Unterschiede im Wohn- und Umweltmodell der fünf Zivilisationstypologien&quot;">​</a></h2><p>Die fünf symbiotischen Zivilisationstypologien haben各自的 Merkmale im Wohn- und Umweltmodell:</p><table tabindex="0"><thead><tr><th>Typologie</th><th>Merkmale des Wohnmodells</th><th>Merkmale des Umweltmodells</th></tr></thead><tbody><tr><td>Ostasiatisch intensiv</td><td>Hohe Dichte, intensiv, hauptsächlich Kollektivheime</td><td>Strenge Aufsicht, effiziente Behandlung, schnelle Wiederherstellung</td></tr><tr><td>Nordeuropäisch Wohlfahrt</td><td>Hohe Sicherheit, hohe Qualität, personalisiert</td><td>Hohe Standards, hohe Investitionen, ökologische Priorität</td></tr><tr><td>Nordamerikanisch pluralistisch</td><td>Marktorientiert, diversifiziert, niedrige Dichte</td><td>Marktaufsicht, technologiegetrieben, Ressourcenschutz</td></tr><tr><td>Europäisch kontinental sozial</td><td>Sozialwohnungen, Genossenschaftswohnungen, ausgewogene Zuweisung</td><td>Organisationsbeteiligung, Beratungsaufsicht, nachhaltige Entwicklung</td></tr><tr><td>Entwicklungsland aufholend</td><td>Sicherheit vorrangig, schneller Bau, schrittweise Verbesserung</td><td>Entwicklung und Schutz gleichermaßen wichtig, Schwerpunktbehandlung</td></tr></tbody></table><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Wohn- und Umweltsicherheit ist der &quot;Grundstein der Lebenshaltung&quot; und die &quot;ökologische Barriere&quot; der Anker-Symbiose-Zivilisation. Durch das mehrstufige Wohnsicherheitssystem, das umfassende Umweltschutzsystem und den wissenschaftlichen Bau des bewohnbaren Raums hat die symbiotische Zivilisation die Ziele &quot;Wer wohnt, hat Haus, ökologische Symbiose, nachhaltige Entwicklung, alle Rassen bewohnbar&quot; verwirklicht. Die Wohnsicherheit ermöglicht es jedem symbiotischen Wesen, in Ruhe zu kultivieren, und der Umweltschutz hat die ökologische Grundlage für die langfristige Entwicklung der Zivilisation gelegt. Beide ergänzen sich gegenseitig und unterstützen gemeinsam den gemeinsamen Fortschritt aller Rassen und die nachhaltige Entwicklung der symbiotischen Zivilisation.</p><h2 id="verwandte-dokumente" tabindex="-1">Verwandte Dokumente <a class="header-anchor" href="#verwandte-dokumente" aria-label="Permalink to &quot;Verwandte Dokumente&quot;">​</a></h2><ul><li>45-住房保障法 (Gesetz über die Wohnsicherheit)</li><li>46-环境保护法 (Umweltschutzgesetz)</li><li>32-北欧福利型文明 (Zivilisation des nordeuropäischen Wohlfahrtstyps)</li></ul>',59)])])}const m=n(s,[["render",u]]);export{c as __pageData,m as default};
